import{_ as s,o as n,a as e,b as l}from"./app.C41L12d5.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"调用","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/invocation/single_operator_api_call"},{"text":"运行时加载机制","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/invocation/runtime_loading_mechanism"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/invocation/runtime_loading_mechanism.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/invocation/runtime_loading_mechanism.md","outlineHeaders":[{"level":2,"title":"1. 算子是如何被调用的","slug":"1.-算子是如何被调用的","link":"#1.-算子是如何被调用的"},{"level":3,"title":"二段式接口","slug":"二段式接口","link":"#二段式接口"},{"level":3,"title":"为什么分两阶段","slug":"为什么分两阶段","link":"#为什么分两阶段"},{"level":3,"title":"Binary匹配机制","slug":"Binary匹配机制","link":"#Binary匹配机制"},{"level":2,"title":"2. 代码写法如何影响运行行为","slug":"2.-代码写法如何影响运行行为","link":"#2.-代码写法如何影响运行行为"},{"level":3,"title":"影响编译产物形态的写法","slug":"影响编译产物形态的写法","link":"#影响编译产物形态的写法"},{"level":4,"title":"TilingKey / 核函数（Kernel）模板的分支数量","slug":"TilingKey-/-核函数（Kernel）模板的分支数量","link":"#TilingKey-/-核函数（Kernel）模板的分支数量"},{"level":4,"title":"ASCEND_SOC_SERIES/ASCEND_COMPUTE_UNIT范围","slug":"ASCEND_SOC_SERIES/ASCEND_COMPUTE_UNIT范围","link":"#ASCEND_SOC_SERIES/ASCEND_COMPUTE_UNIT范围"},{"level":3,"title":"影响Host侧运行开销的写法","slug":"影响Host侧运行开销的写法","link":"#影响Host侧运行开销的写法"},{"level":4,"title":"TilingFunc的计算复杂度","slug":"TilingFunc的计算复杂度","link":"#TilingFunc的计算复杂度"},{"level":4,"title":"TilingData字段数量","slug":"TilingData字段数量","link":"#TilingData字段数量"},{"level":4,"title":"Workspace大小设置","slug":"Workspace大小设置","link":"#Workspace大小设置"},{"level":3,"title":"影响核函数（Kernel）侧执行表现的写法","slug":"影响核函数（Kernel）侧执行表现的写法","link":"#影响核函数（Kernel）侧执行表现的写法"},{"level":4,"title":"TILING_KEY_IS vs运行时if-else","slug":"TILING_KEY_IS-vs运行时if-else","link":"#TILING_KEY_IS-vs运行时if-else"},{"level":4,"title":"核函数（Kernel）模板参数","slug":"核函数（Kernel）模板参数","link":"#核函数（Kernel）模板参数"},{"level":4,"title":"tileNum切分粒度","slug":"tileNum切分粒度","link":"#tileNum切分粒度"},{"level":2,"title":"相关文档","slug":"相关文档","link":"#相关文档"}],"lastUpdated":1788139350000}'),p={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/invocation/runtime_loading_mechanism.md"};function i(c,a,t,r,o,d){return n(),e("div",null,[...a[0]||(a[0]=[l(`<div><article class="markdown-body"><h1>运行时加载机制</h1><p>本文是扩展内容，介绍算子开发完成后，编译产物如何被加载和执行，以及开发时的设计决策如何影响运行表现。本文从算子开发者视角梳理运行时调用的基本模型和代码写法对运行行为的影响。</p><h2 id="1.-算子是如何被调用的">1. 算子是如何被调用的<a class="header-anchor" href="#1.-算子是如何被调用的">​</a></h2><h3 id="二段式接口">二段式接口<a class="header-anchor" href="#二段式接口">​</a></h3><p>单算子API采用二段式调用：<code>aclnnXxxGetWorkspaceSize</code>和<code>aclnnXxx</code>。</p><p><strong>第一阶段：GetWorkspaceSize</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">aclnnXxxGetWorkspaceSize</span><span class="p">(</span><span class="n">input0</span><span class="p">,</span><span class="w"> </span><span class="n">input1</span><span class="p">,</span><span class="w"> </span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="o">&amp;</span><span class="n">workspaceSize</span><span class="p">,</span><span class="w"> </span><span class="o">&amp;</span><span class="n">executor</span><span class="p">);</span>
</code></pre></div><p>此阶段主要在Host侧完成执行前准备：</p><ol><li>根据OpType、SoC、输入输出dtype/format/shape、属性等信息，优先尝试匹配aclnn参数缓存；缓存命中时复用已保存的binary和Tiling执行信息，跳过后续binary匹配和TilingFunc调用。</li><li>缓存未命中时，根据算子注册信息和当前参数匹配可用的核函数（Kernel）binary，或者调用算子注册的TilingFunc计算当前输入对应的TilingData、TilingKey、BlockDim。</li><li>根据匹配到的binary配置和TilingKey，确定本次执行的核函数（Kernel）入口。</li><li>返回workspaceSize（需要分配的Device内存大小）和executor（承载调度上下文）。</li></ol><p>此阶段可能触发的耗时操作：</p><ul><li><strong>TilingFunc调用</strong>：执行Host侧C++函数。</li><li><strong>Binary查找</strong>：在文件系统中检索.o文件，涉及文件I/O。</li></ul><p><strong>第二阶段：Execute</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">aclnnXxx</span><span class="p">(</span><span class="n">workspace</span><span class="p">,</span><span class="w"> </span><span class="n">workspaceSize</span><span class="p">,</span><span class="w"> </span><span class="n">executor</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="p">);</span>
</code></pre></div><p>此阶段将第一阶段准备好的全部信息打包提交到stream上执行。</p><h3 id="为什么分两阶段">为什么分两阶段<a class="header-anchor" href="#为什么分两阶段">​</a></h3><p>两阶段接口的目的是将执行前准备和执行下发分离：调用方可以先获取<code>workspaceSize</code>和<code>executor</code>，再根据自身资源管理方式选择按算子申请、统一内存池分配或复用已有workspace，并在提交核函数（Kernel）前完成内存预算，可以减少频繁申请内存的开销和减少内存碎片。</p><h3 id="Binary匹配机制">Binary匹配机制<a class="header-anchor" href="#Binary匹配机制">​</a></h3><p>运行时框架会基于OpType、目标芯片型号、输入输出dtype/format、shape支持范围、属性以及TilingKey/模板参数组合等信息匹配预编译的核函数（Kernel）binary。</p><p>binary查找的优先级顺序：</p><ul><li>运行时会先加载<code>ASCEND_CUSTOM_OPP_PATH</code>配置路径下的算子包，再查找默认CANN路径下的算子包。</li><li>默认安装到<code>$ASCEND_OPP_PATH/vendors/&lt;vendor_name&gt;</code>的场景下，算子包优先级根据<code>opp/vendors/config.ini</code>中的<code>load_priority</code>决定，排在前面的算子包优先级更高。</li><li>动态库/静态库集成场景的加载方式与RUN包不同，应用直接链接或通过<code>ASCEND_CUSTOM_OPP_PATH</code>配置动态库时，应按<a href="../compilation_and_deployment/dynamic_static_lib_compilation.html">算子动态库和静态库编译</a>中的优先级规则处理。</li></ul><h2 id="2.-代码写法如何影响运行行为">2. 代码写法如何影响运行行为<a class="header-anchor" href="#2.-代码写法如何影响运行行为">​</a></h2><p>开发者在编写算子代码时做出的选择，会直接影响编译产物的形态和运行时的表现。以下按影响阶段分为三类。</p><h3 id="影响编译产物形态的写法">影响编译产物形态的写法<a class="header-anchor" href="#影响编译产物形态的写法">​</a></h3><h4 id="TilingKey-/-核函数（Kernel）模板的分支数量">TilingKey / 核函数（Kernel）模板的分支数量<a class="header-anchor" href="#TilingKey-/-核函数（Kernel）模板的分支数量">​</a></h4><p>算子有两种分支策略可选：<a href="../design_and_implementation/multi_branch_strategy.html#%E4%BD%BF%E7%94%A8tilingkey%E9%80%89%E6%8B%A9%E5%88%86%E6%94%AF">数字TilingKey</a>或<a href="../design_and_implementation/multi_branch_strategy.html#%E4%BD%BF%E7%94%A8kernel%E6%A8%A1%E6%9D%BF%E7%BB%84%E7%BB%87%E5%88%86%E6%94%AF">命名核函数（Kernel）模板参数</a>，两者互斥。</p><table><thead><tr><th>分支策略</th><th>编译耗时</th><th>运行表现</th><th>适用场景</th></tr></thead><tbody><tr><td>单一分支（所有支持输入走同一套核函数（Kernel）逻辑）</td><td>极快</td><td>代码简单，但难以针对不同场景优化。</td><td>简单算子、开发阶段。</td></tr><tr><td>按shape分档（如 ≤64 / ≤1024 / ≤64K / &gt;64K）</td><td>适中</td><td>可针对不同数据规模选择更合适的算法或tile参数。</td><td>大多数算子。</td></tr><tr><td>按shape × dtype × 参数组合精细分档</td><td>较长</td><td>性能特化更充分，但binary数量和包体积增加。</td><td>生产部署、性能敏感。</td></tr></tbody></table><p><strong>开发阶段建议</strong>：少分支或用选择性编译选项只编译当前验证的分支，加速迭代。<strong>生产部署</strong>：确保已发布的二进制配置覆盖实际会调用到的dtype/format、属性、TilingKey或模板参数组合。</p><h4 id="ASCEND_SOC_SERIES/ASCEND_COMPUTE_UNIT范围">ASCEND_SOC_SERIES/ASCEND_COMPUTE_UNIT范围<a class="header-anchor" href="#ASCEND_SOC_SERIES/ASCEND_COMPUTE_UNIT范围">​</a></h4><p>离线编译产物需要包含当前运行芯片型号对应的核函数（Kernel）binary。开发阶段如果只验证单一芯片，可收窄<code>ASCEND_SOC_SERIES</code>或<code>ASCEND_COMPUTE_UNIT</code>；两者不能同时配置。需要跨芯片部署时，再按目标环境配置多个系列或型号。<code>ASCEND_SOC_SERIES</code>的输入大小写不敏感；产物目录和运行时查找规则不变。如果离线编译产物里不包含当前运行芯片的核函数（Kernel）binary，运行时会失败。</p><h3 id="影响Host侧运行开销的写法">影响Host侧运行开销的写法<a class="header-anchor" href="#影响Host侧运行开销的写法">​</a></h3><h4 id="TilingFunc的计算复杂度">TilingFunc的计算复杂度<a class="header-anchor" href="#TilingFunc的计算复杂度">​</a></h4><p>TilingFunc被调用时，如果函数中包含复杂计算（如大量循环、动态内存分配、文件系统操作），会直接增加每次算子调用的Host侧延迟。</p><p><strong>建议</strong>：TilingFunc中只做必要的标量计算（shape推导、分块参数计算），避免复杂逻辑。</p><h4 id="TilingData字段数量">TilingData字段数量<a class="header-anchor" href="#TilingData字段数量">​</a></h4><p>TilingData结构体在Host侧填写、序列化后传递到核函数（Kernel）侧。字段越多，序列化开销越大。</p><p><strong>建议</strong>：TilingData只传核函数（Kernel）需要的标量值，不要传冗余信息。</p><h4 id="Workspace大小设置">Workspace大小设置<a class="header-anchor" href="#Workspace大小设置">​</a></h4><p><code>context-&gt;GetWorkspaceSizes()</code>设置的workspace大小决定了每次调用需要额外分配的Device内存量。workspace越大，内存压力越大。</p><p><strong>建议</strong>：精确计算所需workspace大小，避免预留过多冗余空间。</p><h3 id="影响核函数（Kernel）侧执行表现的写法">影响核函数（Kernel）侧执行表现的写法<a class="header-anchor" href="#影响核函数（Kernel）侧执行表现的写法">​</a></h3><h4 id="TILING_KEY_IS-vs运行时if-else">TILING_KEY_IS vs运行时if-else<a class="header-anchor" href="#TILING_KEY_IS-vs运行时if-else">​</a></h4><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 方式一：TilingKey分支（推荐）</span>
<span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">TILING_KEY_IS</span><span class="p">(</span><span class="mi">1</span><span class="p">))</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">ProcessSmall</span><span class="p">();</span><span class="w">    </span><span class="c1">// 编译期常量折叠，未命中的分支被完全移除</span>
<span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">TILING_KEY_IS</span><span class="p">(</span><span class="mi">2</span><span class="p">))</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">ProcessLarge</span><span class="p">();</span>
<span class="p">}</span>

<span class="c1">// 方式二：运行时分支</span>
<span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">tilingData</span><span class="p">.</span><span class="n">totalLength</span><span class="w"> </span><span class="o">&lt;=</span><span class="w"> </span><span class="n">threshold</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">ProcessSmall</span><span class="p">();</span><span class="w">    </span><span class="c1">// 运行时条件判断，两个分支都在binary中</span>
<span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">ProcessLarge</span><span class="p">();</span>
<span class="p">}</span>
</code></pre></div><p><code>TILING_KEY_IS</code>是编译期常量判断，编译器将未命中的分支完全移除（常量折叠），消除运行时分支判断开销和icache压力。运行时if-else两个分支都保留在binary中，代码体积更大。</p><h4 id="核函数（Kernel）模板参数">核函数（Kernel）模板参数<a class="header-anchor" href="#核函数（Kernel）模板参数">​</a></h4><p>核函数（Kernel）模板使用命名参数（如<code>D_T_X</code>、<code>TILE_NUM</code>）组织模板参数组合，并在Host侧根据实际参数生成和设置TilingKey，从而实现编译期特化：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">D_T_X</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">D_T_Y</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">D_T_Z</span><span class="p">,</span><span class="w"> </span><span class="kt">int</span><span class="w"> </span><span class="n">TILE_NUM</span><span class="o">&gt;</span>
<span class="n">__global__</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(...)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// D_T_X/D_T_Y/D_T_Z在编译期确定，类型判断在编译期完成</span>
<span class="w">    </span><span class="c1">// TILE_NUM在编译期确定，循环边界等可直接展开</span>
<span class="p">}</span>
</code></pre></div><p>模板参数使编译器能够针对特定类型和常量做优化（如循环展开、常量传播）。运行时只需选择已编译的模板组合，不会在核函数（Kernel）内产生模板参数本身的判断开销。</p><h4 id="tileNum切分粒度">tileNum切分粒度<a class="header-anchor" href="#tileNum切分粒度">​</a></h4><p>TilingData中的tileNum决定每个Block上的分块个数：</p><ul><li>tileNum过小 → 每个分块的数据量大，单次搬运耗时长，但循环次数少。</li><li>tileNum过大 → 每个分块的数据量小，循环次数多，循环开销占比增大。</li></ul><p>需要根据Unified Buffer（UB）内存容量和计算/搬运比例选取合适的tileNum。</p><h2 id="相关文档">相关文档<a class="header-anchor" href="#相关文档">​</a></h2><ul><li><a href="../compilation_and_deployment/basic_process.html">基本流程</a> — 编译与部署操作指南。</li><li><a href="../design_and_implementation/host_tiling_implementation.html">Host侧Tiling实现</a> — Tiling函数、TilingData和workspace设置方法。</li><li><a href="../design_and_implementation/multi_branch_strategy.html">多分支策略</a> — TilingKey和核函数（Kernel）模板的配置方法。</li><li><a href="./single_operator_api_call.html">单算子API调用</a> — 两段式接口的使用方法。</li><li><a href="./simplified_key_runtime_flow.html">基于simplified key的运行时选择流程</a> — 回调生成simplified key并选择预编译binary的流程。</li><li><a href="../compilation_and_deployment/dynamic_static_lib_compilation.html">算子动态库和静态库编译</a> — 动态库/静态库形态下的集成方式。</li></ul></article></div>`,1)])])}const g=s(p,[["render",i]]);export{_ as __pageData,g as default};
